import{templates,createProject,validateProject}from'./project.js';
import{mountEditor}from'./editor.js';
import{mountSetup,templateDescriptions}from'./setup.js';
import{paintBackground,paintObject}from'./graphics.js';
const $=s=>document.querySelector(s),app=$('#app');let projects=[],current=null,selected=null,tab='projects',filter='',zoom=1,drag=null,history=[],future=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
try{const saved=JSON.parse(localStorage.getItem('playform.projects')||'[]');projects=saved.map(validateProject);const prefs=JSON.parse(localStorage.getItem('playform.preferences')||'{}');$('#ai').checked=!!prefs.ai;$('#motion').checked=!!prefs.motion;document.body.classList.toggle('reduce-motion',!!prefs.motion)}catch{toast('Saved data could not be read. Import a project backup to recover it.')}
function persist(){try{localStorage.setItem('playform.projects',JSON.stringify(projects));return true}catch{toast('Device storage is unavailable or full. Export a backup before closing.');return false}}
function save(){if(!current)return false;current.updated=Date.now();const i=projects.findIndex(p=>p.id===current.id);if(i<0)projects.unshift(current);else projects[i]=current;const saved=persist();if($('#save-status'))$('#save-status').textContent=saved?'Saved on this device':'Not saved · Export a backup';return saved}
function navigate(next){tab=next;renderHome()}
const art=t=>`<div class="template-art ${t}"><canvas data-preview-template="${t}" aria-hidden="true"></canvas></div>`;
function nav(){return `<button data-nav="projects" class="${tab==='projects'?'active':''}"><span>▦</span> My projects</button><button data-nav="templates" class="${tab==='templates'?'active':''}"><span>◇</span> Templates</button><button data-nav="guide" class="${tab==='guide'?'active':''}"><span>⌘</span> Getting started</button>`}
function templateCards(){return `<div class="templates">${Object.entries(templates).map(([id,name])=>`<button class="template" data-create="${id}">${art(id)}<div class="template-copy"><h3>${name}</h3></div></button>`).join('')}</div>`}
function renderHome(){current=null;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">◈</span><div>Playform <small>Studio</small></div></div><nav>${nav()}</nav><div class="side-bottom"><p><span class="status"></span>Local workspace</p><button data-settings>⚙ Preferences</button><p style="margin:20px 0 0">Playform Studio · 0.1</p></div></aside><main><header class="topbar"><span>WORKSPACE / ${tab==='projects'?'MY PROJECTS':tab.toUpperCase()}</span><button data-settings>⚙ Preferences</button></header><div class="content">${tab==='guide'?`<div class="help-copy"><div class="eyebrow">GETTING STARTED</div><h1>Your idea starts here.</h1><p>Create an empty project or choose a starter scene. Give your project a name to enter the scene editor.</p><h2>Arrange your scene</h2><p>Select an object on the canvas and drag it to move. Use the Inspector to change its name, position, size, and color. Add platforms, coins, players, and hazards from Objects.</p><h2>On your phone</h2><p>Drag objects with one finger. Open Objects or Inspector with the canvas toolbar. Panels collapse so the canvas stays usable.</p><h2>Keep your work</h2><p>Projects save automatically on this device. Use Export in the editor for a JSON backup, and Open project on the start screen to import it.</p><p>This first milestone includes the title screen and scene arrangement. Gameplay, animation, multiplayer, and AI services are not implemented yet.</p><button class="primary" data-create="blank">Create your first project →</button></div>`:`<div class="intro"><div><h1>Playform Studio</h1><div class="actions"><button class="primary" data-create="blank">＋ New project</button><button data-import>↥ Open project</button></div></div><div class="scene-art" aria-hidden="true"><i class="platform" style="bottom:28px;left:25px;width:140px"></i><i class="platform" style="bottom:75px;right:18px;width:65px"></i><i class="player" style="bottom:40px;left:60px"></i><i class="coin" style="bottom:65px;left:115px"></i><i class="coin" style="bottom:105px;right:40px"></i></div></div><div class="section-head"><h2>Start with ${tab==='templates'?'a template':'an idea'}</h2></div>${templateCards()}${tab==='projects'?`<div class="section-head"><h2>Recent projects <span class="muted">${projects.length?`· ${projects.length}`:''}</span></h2><input id="search" type="search" aria-label="Search projects" placeholder="Search projects…" value="${esc(filter)}"></div><div id="recent" class="recent"></div>`:''}`}</div></main><nav class="mobile-nav" aria-label="Main navigation">${nav()}</nav></div>`;bindHome();renderRecent()}
function renderRecent(){const el=$('#recent');if(!el)return;const visible=projects.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>b.updated-a.updated);el.innerHTML=visible.length?visible.map(p=>`<div class="project-row"><span class="project-icon">◇</span><button class="project-open" data-open="${esc(p.id)}">${esc(p.name)}</button><button data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.name)}">×</button></div>`).join(''):`<div class="empty">${filter?'No matching projects':'No projects yet'}</div>`;el.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProject(projects.find(p=>p.id===b.dataset.open)));el.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const p=projects.find(p=>p.id===b.dataset.delete);if(confirm(`Delete “${p.name}” from this device? Export a backup first if you need it.`)){projects=projects.filter(p=>p!==projects.find(p=>p.id===b.dataset.delete));persist();renderHome()}})}
function bindHome(){app.querySelectorAll('[data-preview-template]').forEach(c=>{const p=createProject('Preview',c.dataset.previewTemplate);c.width=480;c.height=270;const ctx=c.getContext('2d');ctx.scale(.5,.5);paintBackground(ctx);for(const o of p.objects)paintObject(ctx,o)});app.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>{$('#template').value=b.dataset.create;$('#create').showModal();$('#project-name').focus()});app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));app.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>$('#settings').showModal());app.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>$('#import').click());if($('#search'))$('#search').oninput=e=>{filter=e.target.value;renderRecent()}}
let disposeEditor;
function openProject(p){disposeEditor?.();current=p;disposeEditor=mountEditor({root:app,project:p,onSave:()=>save(),onHome:(newProject)=>{current=null;renderHome();if(newProject){$('#create').showModal();$('#project-name').focus()}},onImport:()=>$('#import').click(),onPreferences:()=>$('#settings').showModal(),notify:toast})}
function setupProject(p){disposeEditor?.();disposeEditor=null;current=null;mountSetup({root:app,project:p,onComplete:()=>openProject(p),onCancel:()=>renderHome(),notify:toast})}
$('#template').innerHTML=Object.entries(templates).map(([id,name])=>`<option value="${id}">${name}</option>`).join('');
$('#create-form').onsubmit=e=>{e.preventDefault();try{const p=createProject($('#project-name').value,$('#template').value);$('#create').close();$('#create-form').reset();setupProject(p)}catch(e){toast(e.message)}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Project files must be smaller than 5 MB.');const p=validateProject(JSON.parse(await file.text()));p.id=crypto.randomUUID();openProject(p);save();toast('Project imported.')}catch(error){toast(error.message)}e.target.value=''};
for(const selector of ['#ai','#motion'])$(selector).onchange=()=>{const prefs={ai:$('#ai').checked,motion:$('#motion').checked};document.body.classList.toggle('reduce-motion',prefs.motion);try{localStorage.setItem('playform.preferences',JSON.stringify(prefs))}catch{toast('Preferences could not be saved.')}};
renderHome();
